// Support binding to limited Map destinations:
// - map[string][]string,
// - map[string]string,
// - map[string]interface{}
// - map[string]int, map[string]int8, map[string]int16, map[string]int32, map[string]int64
// - map[string]uint, map[string]uint8, map[string]uint16, map[string]uint32, map[string]uint64
// - map[string]bool, map[string]float64, map[string]float32
// - map[string]time.Time
// - map[string]json.Number
if typ.Kind() == reflect.Map && typ.Key().Kind() == reflect.String {
	k := typ.Elem().Kind()
	isElemInterface := k == reflect.Interface
	isElemString := k == reflect.String
	isElemSlice := k == reflect.Slice
	isElemBool := k == reflect.Bool
	isElemInt := k >= reflect.Int && k <= reflect.Int64
	isElemUint := k >= reflect.Uint && k <= reflect.Uint64
	isElemFloat := k >= reflect.Float32 && k <= reflect.Float64
	isElemTime := k == reflect.Struct && typ.Elem().ConvertibleTo(reflect.TypeOf(time.Time{}))
	isElemJSONNumber := k == reflect.Struct && typ.Elem().ConvertibleTo(reflect.TypeOf(json.Number("")))

	if isElemInterface || isElemString || isElemSlice || isElemBool || isElemInt || isElemUint || isElemFloat || isElemTime || isElemJSONNumber {
		if val.IsNil() {
			val.Set(reflect.MakeMap(typ))
		}
		tmp := reflect.New(typ.Elem()).Elem()
		for k, v := range data {
			if isElemInterface || isElemString {
				val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v[0]))
			} else if isElemSlice {
				val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v))
			} else {
				if err := setWithProperType(tmp.Kind(), v[0], tmp); err != nil {
					return err
				}
				val.SetMapIndex(reflect.ValueOf(k), tmp)
			}
		}
		return nil
	}
}

