func TestZZFuzz3(t *testing.T) {
	segPool := []string{"a", "b", ":p", ":q", "*", ""}
	rng := rand.New(rand.NewSource(1234))
	panics := 0
	nils := 0
	reported := map[string]bool{}
	for iter := 0; iter < 30000; iter++ {
		e := New()
		r := e.router
		nRoutes := 1 + rng.Intn(6)
		var routes []string
		for i := 0; i < nRoutes; i++ {
			nSeg := 1 + rng.Intn(4)
			p := ""
			for j := 0; j < nSeg; j++ {
				p += "/" + segPool[rng.Intn(len(segPool))]
			}
			routes = append(routes, p)
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						key := "ADD" + fmt.Sprint(rec)
						if !reported[key] {
							reported[key] = true
							t.Errorf("PANIC Add(%q) routes=%v: %v", p, routes, rec)
						}
					}
				}()
				r.Add(http.MethodGet, p, handlerFunc)
			}()
		}
		for k := 0; k < 12; k++ {
			// build path with random leading char
			q := ""
			if rng.Intn(10) != 0 {
				q = "/"
			}
			nSeg := rng.Intn(5)
			for j := 0; j < nSeg; j++ {
				q += segPool[rng.Intn(3)]
				if j != nSeg-1 {
					q += "/"
				}
			}
			if rng.Intn(10) == 0 {
				q = ""
			}
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						panics++
						key := fmt.Sprint(rec)
						if !reported[key] {
							reported[key] = true
							t.Errorf("PANIC Find(%q) routes=%v: %v", q, routes, rec)
						}
					}
				}()
				c := e.NewContext(nil, nil).(*context)
				r.Find(http.MethodGet, q, c)
				if c.handler == nil {
					nils++
					if nils < 5 {
						t.Errorf("nil handler Find(%q) routes=%v", q, routes)
					}
				}
			}()
		}
	}
	fmt.Println("total panics:", panics, "nil handlers:", nils)
}
EOF
